package com.zhineng.platform.evaluation.performance;
import static org.junit.jupiter.api.Assertions.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;
import com.fasterxml.jackson.databind.ObjectMapper;import com.zhineng.platform.common.audit.OperationLogRepository;import com.zhineng.platform.common.database.*;import com.zhineng.platform.common.user.repository.UserRepository;import com.zhineng.platform.common.user.service.CurrentUserService;import com.zhineng.platform.evaluation.performance.controller.*;import com.zhineng.platform.evaluation.performance.dto.PerformanceDtos;import com.zhineng.platform.evaluation.performance.excel.PerformanceExcelService;import com.zhineng.platform.evaluation.performance.repository.PerformanceRepository;import com.zhineng.platform.evaluation.performance.service.PerformanceService;import com.zhineng.platform.evaluation.performance.storage.PerformanceStorageService;
import java.io.*;import java.nio.file.Path;import java.util.*;import javax.sql.DataSource;import org.apache.poi.xssf.usermodel.XSSFWorkbook;import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;import org.springframework.boot.DefaultApplicationArguments;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.mock.env.MockEnvironment;import org.springframework.mock.web.MockMultipartFile;import org.springframework.test.web.servlet.*;
import org.springframework.test.web.servlet.setup.MockMvcBuilders;
class PerformanceTest{
 @TempDir Path temp;
 @Test void importsMixedRowsSelectsLatestAndAppliesOnlyConfirmedCorrection()throws Exception{
  Fixture f=fixture();Map<String,Object> org=f.repository.activeOrg();String code=org.get("unit_code").toString(),name=org.get("unit_name").toString();
  assertTrue(f.service.template().length>100);
  Map<String,Object> first=f.service.importFile(xlsx(code,name,"A",91.5,true));assertEquals(1L,num(first.get("success_rows")));assertEquals(1L,num(first.get("failed_rows")));
  Map<String,Object> second=f.service.importFile(xlsx(code,name,"B",84.0,false));assertEquals(1L,num(second.get("success_rows")));
  Map<String,Object> effective=f.service.records(2026).get(0);assertEquals("B",effective.get("performance_grade"));long rawId=num(effective.get("id"));
  long rawCount=f.jdbc.queryForObject("SELECT count(*) FROM org_performance_raw_records",Long.class);
  Map<String,Object> correction=f.service.saveCorrection(null,new PerformanceDtos.CorrectionRequest(rawId,"ALL","A",93.0,"优秀","补充重点工作证明",null));
  long cid=num(correction.get("id"));
  correction=f.service.submit(cid,new PerformanceDtos.ReviewRequest(null,"提交",integer(correction.get("row_version"))));
  correction=f.service.review(cid,new PerformanceDtos.ReviewRequest("REJECT","证明不足",integer(correction.get("row_version"))));
  correction=f.service.saveCorrection(cid,new PerformanceDtos.CorrectionRequest(rawId,"ALL","A",92.0,"优秀","补充完整证明",integer(correction.get("row_version"))));
  MockMultipartFile proof=new MockMultipartFile("file","proof.pdf","application/pdf","proof".getBytes());assertNotNull(f.service.upload(cid,"证明材料",proof).get("id"));
  correction=f.service.submit(cid,new PerformanceDtos.ReviewRequest(null,"重新提交",integer(correction.get("row_version"))));
  correction=f.service.review(cid,new PerformanceDtos.ReviewRequest("CONFIRM","确认修正",integer(correction.get("row_version"))));
  assertEquals("CONFIRMED",correction.get("status"));effective=f.service.records(2026).get(0);assertEquals("A",effective.get("effective_grade"));assertEquals(92.0,((Number)effective.get("effective_key_work_score")).doubleValue());assertEquals("B",effective.get("performance_grade"));assertEquals(rawCount,f.jdbc.queryForObject("SELECT count(*) FROM org_performance_raw_records",Long.class));
  Map<String,Object> mapping=f.service.saveMapping(null,new PerformanceDtos.MappingRequest("绩效等级","PERFORMANCE_GRADE",false,80,null));assertEquals("PERFORMANCE_GRADE",mapping.get("target_field"));
  new DatabaseMigrationRunner(f.ds).run(new DefaultApplicationArguments(new String[0]));assertEquals(1,f.jdbc.queryForObject("SELECT count(*) FROM schema_migrations WHERE version='11'",Integer.class));assertEquals(1,f.jdbc.queryForObject("PRAGMA foreign_keys",Integer.class));
 }
 @Test void controllerQueriesWork()throws Exception{Fixture f=fixture();MockMvc mvc=MockMvcBuilders.standaloneSetup(new PerformanceController(f.service)).setControllerAdvice(new PerformanceExceptionHandler()).build();mvc.perform(get("/api/org-performance/mappings")).andExpect(status().isOk());mvc.perform(get("/api/org-performance/imports")).andExpect(status().isOk());mvc.perform(get("/api/org-performance/records")).andExpect(status().isOk());mvc.perform(get("/api/org-performance/corrections")).andExpect(status().isOk());mvc.perform(get("/api/org-performance/import-template")).andExpect(status().isOk());}
 private MockMultipartFile xlsx(String code,String name,String grade,double score,boolean invalid)throws Exception{try(XSSFWorkbook wb=new XSSFWorkbook();ByteArrayOutputStream out=new ByteArrayOutputStream()){var s=wb.createSheet();String[] h={"机构编码","机构名称","年度","绩效等次","重点工作得分","班子评价","备注"};var header=s.createRow(0);for(int i=0;i<h.length;i++)header.createCell(i).setCellValue(h[i]);Object[][] rows=invalid?new Object[][]{{code,name,2026,grade,score,"优秀","ok"},{"NO-SUCH","错误机构",2026,"A",90,"良好","bad"}}:new Object[][]{{code,name,2026,grade,score,"良好","latest"}};for(int r=0;r<rows.length;r++){var row=s.createRow(r+1);for(int c=0;c<h.length;c++){Object v=rows[r][c];if(v instanceof Number n)row.createCell(c).setCellValue(n.doubleValue());else row.createCell(c).setCellValue(v.toString());}}wb.write(out);return new MockMultipartFile("file","performance.xlsx","application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",out.toByteArray());}}
 private Fixture fixture()throws Exception{Path db=temp.resolve("p.sqlite");DataSource ds=new SQLiteDataSourceConfig().dataSource(new MockEnvironment().withProperty("app.database.path",db.toString()));new DatabaseMigrationRunner(ds).run(new DefaultApplicationArguments(new String[0]));JdbcTemplate jdbc=new JdbcTemplate(ds);PerformanceRepository repo=new PerformanceRepository(jdbc);PerformanceService service=new PerformanceService(repo,new PerformanceExcelService(),new CurrentUserService(new UserRepository(jdbc),"zhang.zhuren"),new OperationLogRepository(jdbc),new PerformanceStorageService(temp.resolve("storage").toString()),new ObjectMapper());return new Fixture(ds,jdbc,repo,service);}
 private long num(Object v){return((Number)v).longValue();}private int integer(Object v){return((Number)v).intValue();}
 private record Fixture(DataSource ds,JdbcTemplate jdbc,PerformanceRepository repository,PerformanceService service){}
}
